"""English version of the explanatory text of each lesson (shown when the UI language is English)."""


def E(description, usage, notes=None, compare=None, signals=None, explanations=None, formula=None, mistakes=None):
    out = {"description": description, "usage": usage}
    for k, v in (("notes", notes), ("compare", compare), ("signals", signals), ("explanations", explanations), ("formula", formula)):
        if v:
            out[k] = v
    if mistakes:
        out["common_mistakes"] = [{"wrong": w, "right": r} for w, r in mistakes]
    return out


